from string import ascii_lowercase
from collections import Counter

def caesar_decrypt(ciphertext, shift):
    table = str.maketrans(ascii_lowercase,
        ascii_lowercase[shift:] + ascii_lowercase[:shift])
    return ciphertext.translate(table)

def vigenere_decrypt(ciphertext, key):
    key = [ascii_lowercase.index(c) for c in key.lower() if c in ascii_lowercase]
    pt = []
    for i, c in enumerate(ciphertext):
        if c in ascii_lowercase:
            shift = key[i % len(key)]
            idx = (ascii_lowercase.index(c) - shift) % 26
            pt.append(ascii_lowercase[idx])
        else:
            pt.append(c)
    return ''.join(pt)

def try_caesar_all(ciphertext):
    candidates = []
    for shift in range(1,26):
        pt = caesar_decrypt(ciphertext, shift)
        if 'flag{' in pt:
            candidates.append((shift, pt))
        else:
            candidates.append((shift, pt))
    return candidates

def prep_keys_from_ramblings():
    with open('/home/ctfplayer/ctf_files/ramblings') as f:
        r = f.read().lower().replace("'",'').replace('.', '').replace(',', '')
    words = set()
    for line in r.splitlines():
        for w in line.split():
            if 2 <= len(w) <= 10 and w.isalpha():
                words.add(w)
    # Challenge text explicit keys
    words.update(['boss','guard','qwerty','flag','quiz'])
    return sorted(words, key=len)

def main():
    with open('/home/ctfplayer/ctf_files/message') as f:
        ct = f.read().replace('\n','').strip()
    print(f"[*] Ciphertext: {ct}")
    # --- Caesar ---
    print("\n[*] Caesar brute force:")
    caesars = try_caesar_all(ct)
    for shift, pt in caesars:
        if 'flag{' in pt[:30] or pt[:10] == 'flag{':
            print(f"[!] Shift {shift}: {pt}")
        elif shift <= 3 or shift >= 23:
            print(f"Shift {shift}: {pt[:42]}")
    # --- Vigenère ---
    print("\n[*] Vigenère candidates:")
    keys = prep_keys_from_ramblings()
    for k in keys:
        pt = vigenere_decrypt(ct, k)
        if 'flag{' in pt:
            print(f"[!] Key {k}: {pt}")
        elif k in ['boss','guard','quiz','qwerty','flag']:
            print(f"Key {k}: {pt[:42]}")
    # --- Substitution (partial flag pattern search) ---
    print("\n[*] Partial patterns near start:")
    for idx in range(len(ct)-5):
        window = ct[idx:idx+6]
        # look for patterns that resemble 'flag{', e.g. start of pt.
        if Counter(window)['f']>=1 and Counter(window)['l']>=1:
            print(f"Window {idx}: {window}")

if __name__ == '__main__':
    main()

