from string import ascii_lowercase
import re

def prepare_key(keyword):
    # Clean the keyword and create a Playfair table (omit 'j', merge with i)
    seen = set()
    key_table = []
    keyword = keyword.lower().replace('j', 'i')
    for c in keyword:
        if c in ascii_lowercase and c not in seen:
            key_table.append(c)
            seen.add(c)
    for c in ascii_lowercase:
        if c == 'j':
            continue
        if c not in seen:
            key_table.append(c)
            seen.add(c)
    table = [key_table[i:i+5] for i in range(0, 25, 5)]
    return table

def find_position(table, letter):
    letter = 'i' if letter == 'j' else letter
    for r, row in enumerate(table):
        for c, l in enumerate(row):
            if l == letter:
                return (r, c)
    return None

def decode_pair(a, b, table):
    ra, ca = find_position(table, a)
    rb, cb = find_position(table, b)
    if ra == rb:
        ca = (ca - 1) % 5
        cb = (cb - 1) % 5
        return table[ra][ca] + table[rb][cb]
    elif ca == cb:
        ra = (ra - 1) % 5
        rb = (rb - 1) % 5
        return table[ra][ca] + table[rb][cb]
    else:
        return table[ra][cb] + table[rb][ca]

def playfair_decrypt(ciphertext, keyword):
    table = prepare_key(keyword)
    plaintext = ''
    # convert ciphertext to pairs, replacing j->i, preserving only a-z
    msg = re.sub(r'[^a-z]', '', ciphertext.lower()).replace('j', 'i')
    if len(msg) % 2 != 0:
        msg += 'x'  # pad if needed
    for i in range(0, len(msg), 2):
        a = msg[i]
        b = msg[i+1]
        plaintext += decode_pair(a, b, table)
    return plaintext

